// Check that %u works for a string constant whose vector value exactly
// fills the VPI result buffer (2048 characters).

module test;
  reg [8*2048-1:0] text;
  reg [31:0] high_bytes;

  initial begin
    $sformat(text, "%u", "");
    $sformat(high_bytes, "%u", "\377\200AB");
    if (text !== {512{"ABCD"}} || high_bytes !== {8'hff, 8'h80, "AB"})
      $display("FAILED");
    else
      $display("PASSED");
  end
endmodule
